list_shipping_methods.code:
var response = await client.ShippingMethods.ListShippingMethodsAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var shippingMethod in ((IReadOnlyList<object?>)body["shipping_methods"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{shippingMethod["id"]} {shippingMethod["name"]} {shippingMethod["is_default"]}");

